<script setup lang="ts">
import {computed} from 'vue'
import {splitPaths} from '../templates'
import type {ChartPoint} from '../templates'
const props=defineProps<{title:string;points:ChartPoint[];start:number;end:number;peak:number;event?:number;maxGap:number;bars?:boolean}>()
const data=computed(()=>props.points.filter(p=>p.t>=props.start&&p.t<=props.end&&Number.isFinite(p.v)))
const bounds=computed(()=>{const all=data.value.flatMap(p=>[p.v,p.low??p.v,p.high??p.v]);if(props.bars)all.push(0);let min=Math.min(...all),max=Math.max(...all);if(!all.length)return [0,1];if(min===max){min-=Math.abs(min)*.05||.001;max+=Math.abs(max)*.05||.001}return [min,max]})
const x=(t:number)=>55+(t-props.start)/Math.max(1,props.end-props.start)*720
const y=(v:number)=>150-(v-bounds.value[0]!)/(bounds.value[1]!-bounds.value[0]!)*120
const paths=computed(()=>splitPaths(data.value,props.maxGap).map(line=>line.map(p=>`${x(p.t)},${y(p.v)}`).join(' ')))
const fmt=(v:number)=>Math.abs(v)>=1000000?(v/1000000).toFixed(2)+'M':Math.abs(v)>=1000?v.toFixed(0):v.toPrecision(4)
</script><template><figure class="research-chart"><figcaption>{{title}}<span>{{data.length}} 个观测点</span></figcaption><p v-if="!data.length">此区间缺少数据，不补线。</p><svg v-else viewBox="0 0 800 185" role="img" :aria-label="title"><line x1="55" x2="775" y1="150" y2="150" stroke="#33424c"/><text x="2" y="35">{{fmt(bounds[1]!)}}</text><text x="2" y="150">{{fmt(bounds[0]!)}}</text><line :x1="x(peak)" :x2="x(peak)" y1="25" y2="150" stroke="#a48b50" stroke-dasharray="4 4"/><line v-if="event!=null" :x1="x(event)" :x2="x(event)" y1="25" y2="150" stroke="#e77f89" stroke-dasharray="2 4"/><template v-if="bars"><line v-for="p in data" :key="p.t" :x1="x(p.t)" :x2="x(p.t)" :y1="y(0)" :y2="y(p.v)" :stroke="p.v<0?'#ed8993':'#66dcb2'" stroke-width="4"><title>{{new Date(p.t).toLocaleString('zh-CN')}}：{{p.v}}</title></line></template><template v-else><line v-for="p in data.filter(p=>p.low!=null&&p.high!=null)" :key="p.t" :x1="x(p.t)" :x2="x(p.t)" :y1="y(p.low!)" :y2="y(p.high!)" stroke="#5c9181" opacity=".45"><title>{{new Date(p.t).toLocaleString('zh-CN')}} · {{p.low}}～{{p.high}}</title></line><polyline v-for="(path,i) in paths" :key="i" :points="path" fill="none" stroke="#66dcb2" stroke-width="1.8"/></template><text x="55" y="177">{{new Date(start).toLocaleString('zh-CN')}}</text><text x="520" y="177">{{new Date(end).toLocaleString('zh-CN')}}</text></svg></figure></template>
<style scoped>.research-chart{margin:18px 0;padding:16px;background:#0d151c;border:1px solid #26343e;border-radius:6px;min-width:0}.research-chart figcaption{font-size:12px;color:#b9c8d5;display:flex;justify-content:space-between;gap:10px}.research-chart figcaption span{color:#718598}.research-chart svg{display:block;width:100%;margin-top:10px}.research-chart text{fill:#8798aa;font-size:10px}</style>
